import{_ as a,o as i,c as n,a6 as t}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"注册商与域名账号安全","description":"域名被劫持是唯一能让你所有技术防线一次性归零的攻击——注册商账号怎么被打下来、域名锁是什么、转移锁与 DNSSEC 怎么配，以及一份 10 分钟能做完的加固清单。","frontmatter":{"title":"注册商与域名账号安全","description":"域名被劫持是唯一能让你所有技术防线一次性归零的攻击——注册商账号怎么被打下来、域名锁是什么、转移锁与 DNSSEC 怎么配，以及一份 10 分钟能做完的加固清单。","source":"https://daiw.org/manual/web-security/registrar-security"},"headers":[],"relativePath":"manual/computer-programming/web-security/registrar-security.md","filePath":"manual/computer-programming/web-security/registrar-security.md"}'),e={name:"manual/computer-programming/web-security/registrar-security.md"};function l(r,s,p,h,o,d){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="注册商与域名账号安全" tabindex="-1">注册商与域名账号安全 <a class="header-anchor" href="#注册商与域名账号安全" aria-label="Permalink to &quot;注册商与域名账号安全&quot;">​</a></h1><p>域名被劫持是唯一能让你所有技术防线一次性归零的攻击——注册商账号怎么被打下来、域名锁是什么、转移锁与 DNSSEC 怎么配，以及一份 10 分钟能做完的加固清单。</p><p>这一章排在整个专栏最前面，理由很简单：</p><blockquote><p><strong>域名被劫持之后，你的 Nginx 配置、WAF 规则、CSP、参数化查询——一行都不会被执行。</strong> 用户访问的是攻击者的服务器，你的日志里一片安静。</p></blockquote><p>这是唯一一类能让<strong>全部</strong>技术防线同时归零的攻击。而它的防御成本，大概是十分钟。</p><h2 id="攻击者怎么拿到你的域名" tabindex="-1">攻击者怎么拿到你的域名 <a class="header-anchor" href="#攻击者怎么拿到你的域名" aria-label="Permalink to &quot;攻击者怎么拿到你的域名&quot;">​</a></h2><p>真实案例里，路径高度集中在这几条：</p><table tabindex="0"><thead><tr><th>路径</th><th>具体做法</th></tr></thead><tbody><tr><td><strong>撞库</strong></td><td>你在别处泄露的密码，拿来试注册商账号。<strong>这是最常见的一条</strong></td></tr><tr><td><strong>邮箱沦陷</strong></td><td>攻破你的注册邮箱 → 走「忘记密码」流程 → 接管账号</td></tr><tr><td><strong>社工客服</strong></td><td>伪造身份联系注册商人工客服，申请重置</td></tr><tr><td><strong>域名过期</strong></td><td>忘记续费，被抢注（这不需要任何技术）</td></tr><tr><td><strong>DNS 服务商账号</strong></td><td>域名没丢，但 DNS 托管方的账号被打下来，照样能改解析</td></tr></tbody></table><p>注意第二条和第五条：<strong>你的域名安全，取决于注册邮箱的安全和 DNS 服务商账号的安全</strong>。链条比想象的长。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>最容易被忽略的是「域名过期」。</strong> 它不是攻击，是运维失误，但后果一模一样——而且更难挽回，因为域名一旦被别人合法注册，你几乎要不回来。</p><p>有价值的域名会被抢注机器人盯着，<strong>过期当天就没了</strong>。一定要开自动续费，并且确认<strong>绑定的付款方式没过期</strong>——信用卡到期导致自动续费失败是真实且常见的翻车方式。</p></div><h2 id="五道锁-逐个上" tabindex="-1">五道锁，逐个上 <a class="header-anchor" href="#五道锁-逐个上" aria-label="Permalink to &quot;五道锁，逐个上&quot;">​</a></h2><h3 id="一、账号本身" tabindex="-1">一、账号本身 <a class="header-anchor" href="#一、账号本身" aria-label="Permalink to &quot;一、账号本身&quot;">​</a></h3><ul><li><strong>独立且随机的密码</strong>，密码管理器生成，绝不与任何其它站点复用。</li><li><strong>开二次验证，且尽量不用短信</strong>。短信可被 SIM 卡劫持（补卡攻击）。优先级：硬件密钥（FIDO2）&gt; TOTP 应用 &gt; 短信。</li><li><strong>注册邮箱单独用一个</strong>，这个邮箱本身也要开 2FA，且不用它订阅任何东西——减少它出现在泄露库里的机会。</li></ul><h3 id="二、注册商锁-registrar-lock" tabindex="-1">二、注册商锁（Registrar Lock） <a class="header-anchor" href="#二、注册商锁-registrar-lock" aria-label="Permalink to &quot;二、注册商锁（Registrar Lock）&quot;">​</a></h3><p>也叫 <code>clientTransferProhibited</code>，防止域名被转移到别的注册商。<strong>绝大多数注册商默认开启，但值得确认一次</strong>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whois</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;status&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>你想看到这些状态：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Domain Status: clientTransferProhibited</span></span>
<span class="line"><span>Domain Status: clientUpdateProhibited</span></span>
<span class="line"><span>Domain Status: clientDeleteProhibited</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>三个都在，意味着<strong>转移、修改、删除都需要先手动解锁</strong>——攻击者即使登进了后台，也要多迈一道坎。</p><h3 id="三、注册局锁-registry-lock" tabindex="-1">三、注册局锁（Registry Lock） <a class="header-anchor" href="#三、注册局锁-registry-lock" aria-label="Permalink to &quot;三、注册局锁（Registry Lock）&quot;">​</a></h3><p>比注册商锁更硬的一档：<code>serverTransferProhibited</code> 系列，改动需要注册局层面的人工核验（通常是电话确认）。</p><ul><li>需要单独申请，一般收费。</li><li>对个人博客过度；<strong>对承载业务的核心域名值得</strong>。</li><li>大公司的主域名基本都上了这一层。</li></ul><h3 id="四、dnssec" tabindex="-1">四、DNSSEC <a class="header-anchor" href="#四、dnssec" aria-label="Permalink to &quot;四、DNSSEC&quot;">​</a></h3><p>给 DNS 应答加数字签名，防止解析结果在传输途中被篡改。细节见<a href="/Front2Full/manual/computer-programming/web-security/dns-hardening">下一章</a>，这里只强调一点：<strong>DNSSEC 防的是解析链路被投毒，防不了「攻击者登录你的后台合法地改了记录」</strong>。两者要分清，别指望它替代账号安全。</p><h3 id="五、变更告警" tabindex="-1">五、变更告警 <a class="header-anchor" href="#五、变更告警" aria-label="Permalink to &quot;五、变更告警&quot;">​</a></h3><p>把「有人动了我的域名」变成一个能收到的通知：</p><ul><li>注册商后台开启<strong>变更邮件/短信通知</strong>。</li><li>用外部服务监控 NS 与 A 记录变化。</li><li>自己写个定时检查也行：</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/usr/bin/env bash</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 存一份基线，每天比对 NS 记录有没有变</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXPECTED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ns1.example-dns.com ns2.example-dns.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ACTUAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; &#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xargs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ACTUAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EXPECTED</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;⚠️ NS 记录变了：</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ACTUAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 这里接你的告警通道</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>为什么值得做</strong>：域名劫持的黄金处置窗口是最初几小时。等到用户来问「你网站怎么跳到赌博页了」，损失已经造成——搜索引擎可能已经把你标红。</p><h2 id="一个真实的失效模式-管理员邮箱指向自己的域名" tabindex="-1">一个真实的失效模式：管理员邮箱指向自己的域名 <a class="header-anchor" href="#一个真实的失效模式-管理员邮箱指向自己的域名" aria-label="Permalink to &quot;一个真实的失效模式：管理员邮箱指向自己的域名&quot;">​</a></h2><p>这是个很隐蔽的循环依赖：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com 的注册商账号</span></span>
<span class="line"><span>   → 注册邮箱是 admin@example.com</span></span>
<span class="line"><span>      → 这个邮箱的 MX 记录在 example.com 的 DNS 里</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>一旦域名解析被改，<strong>攻击者顺手把 MX 指向自己的邮件服务器，你的找回密码邮件直接落到他手上</strong>。你连申诉的通道都被切断了。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>对策：注册邮箱一定要用另一个域名</strong>，最好是主流邮件服务商的独立地址（并单独开 2FA）。这个建议看起来琐碎，但它切断的是一条会让你彻底失去控制权的依赖环。</p></div><h2 id="_10-分钟加固清单" tabindex="-1">10 分钟加固清单 <a class="header-anchor" href="#_10-分钟加固清单" aria-label="Permalink to &quot;10 分钟加固清单&quot;">​</a></h2><p>逐条打勾：</p><ul><li>[ ] 注册商账号用独立随机密码</li><li>[ ] 注册商账号开 2FA（优先硬件密钥 / TOTP，避免纯短信）</li><li>[ ] <strong>注册邮箱不在本域名下</strong>，且它自己也开了 2FA</li><li>[ ] <code>whois</code> 确认三个 <code>client*Prohibited</code> 状态都在</li><li>[ ] 自动续费已开，且<strong>付款方式未过期</strong></li><li>[ ] 域名到期日已记进日历（不要只依赖自动续费）</li><li>[ ] DNS 服务商账号同样开 2FA</li><li>[ ] 开启域名变更通知，或配了 NS 记录监控</li><li>[ ] 核心业务域名评估是否上注册局锁</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>域名劫持是唯一能让全部技术防线一次性作废的攻击，且你的日志看不到。</li><li>最常见的入口是<strong>撞库</strong>和<strong>注册邮箱沦陷</strong>，不是什么高深手法。</li><li><strong>域名过期</strong>造成的后果与被劫持等同，且更难挽回。</li><li>注册邮箱绝对不要放在本域名下，那是一条会致命的循环依赖。</li></ul><p>下一章讲 DNS 记录本身怎么加固。👉 <a href="/Front2Full/manual/computer-programming/web-security/dns-hardening">DNS 加固：DNSSEC 与 CAA</a></p>`,40)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
